    if els[i]=='Ru': continue
    nb=[]
    for j in range(n):
        if i==j: continue
        if np.linalg.norm(xyz[i]-xyz[j])<1.25*(rc[els[i]]+rc[els[j]]): nb.append(els[j]+str(j))
    exp={'H':1,'C':None,'N':3}
    if els[i]=='H' and len(nb)!=1: print('H prob',i,nb)
    if els[i]=='N' and len(nb)!=3: print('N prob',i,nb)
